*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDBNS22300.xml";
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 목록을 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    if ($c.stf.compareFromToDate2(edt_Sdd, edt_Edd) == false) return;
    var param = '';
    param += "&{P}V_STD_CD=" + $c.stf.getObjectValue(txb_pSTD_CD); //표준코드
    param += "&{P}V_ISU_KOR_NM=" + $c.stf.getObjectValue(txb_pISU_KOR_NM); //한글종목명
    param += "&{P}V_ISUR_NM=" + $c.stf.getObjectValue(txb_IsurNm); //발행기관코드
    param += "&{P}V_SRI_BND_TP_CD=" + $c.stf.getObjectValue(cmb_pSRI_BND_TP_CD); //SRI채권구분
    param += "&{P}V_SDD=" + $c.stf.getObjectValue(edt_Sdd); //신청일시작일
    param += "&{P}V_EDD=" + $c.stf.getObjectValue(edt_Edd); //신청일종료일

    var dsNm = 'BNSSRI_APPL_LIST';
    var qryId = 'lds.stf.bnslistbzappl.select.sriBndFileLstmStat';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_NM: $c.stf.getObjectValue(txb_IsurNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_IsurNm, arrPar[0].ISUR_NM);
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), "STD_CD"),
        ISUR_CD: dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD"),
        APPL_ISU_SEQ: dts_List.getCellData(dts_List.getRowPosition(), "APPL_ISU_SEQ"),
        SRI_BND_TP_CD: dts_List.getCellData(dts_List.getRowPosition(), "SRI_BND_TP_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/******************************************************************* 
 * 함수명   : fn_PopAttachDocSearch
 * 설명     : 첨부문서 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_PopAttachDocSearchSri = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS22301", "/bnslistbzappl/ULDBNS22301.gfm", "ESG채권 첨부문서 조회", obj_left, obj_top, 900, 450, "window");
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터 정의 (채권시장조치구분코드)
 ***********************************************/
scwin.fn_SetComboCode = function() {
    var arrCid = [];
    arrCid.push({
        cid: '03057',
        cnm: 'cmb_MktactTpCd'
    });
    $c.bns.fn_SetBnsComboToCode2(scwin.vScrenID, dts_Temp, arrCid, 'ALL');
};
scwin.gform_onload = function() {
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    //처리기간설정
    $c.stf.fn_setFromToDate(1, edt_Sdd, edt_Edd);
    //setObjectValue(edt_Edd, cGetToday("yyyymmdd"));
    //채권시장조치구분코드
    //fn_SetComboCode();
    //목록조회
    scwin.fn_Search();
};
scwin.img_Sdate_onclick = function() {
    popUpCalendar2(edt_Sdd);
};
scwin.img_Edate_onclick = function() {
    popUpCalendar2(edt_Edd);
};
scwin.bnt_Select_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewOffice(grd_List, "sheet1", "", 8, 0);
};
scwin.img_IsurNm_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(img_IsurNm);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.grd_List_OnDblClick = function(row, colid) {
    if (row > 0) {
        scwin.fn_GetPar = fn_GetCommonKey;
        scwin.fn_PopAttachDocSearchSri(grd_List);
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.txb_IsurNm_onkeypress = function() {
    if ($c.stf.compareFromToDate2(edt_Sdd, edt_Edd)) {
        if (window.event.keyCode == 13) scwin.fn_Search();
    }
};
scwin.cmb_pSRI_BND_TP_CD_OnSelChange = function() {
    scwin.fn_Search();
};
scwin.txb_pSTD_CD_onkeyup = function() {
    if (txb_pSTD_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.fn_Search();
        } else {

        }
    }
};
scwin.txb_pISU_KOR_NM_onkeyup = function() {
    if (txb_pISU_KOR_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.fn_Search();
        } else {

        }
    }
};
